------------ import ------------
local kTool = CS.Engine.Lib.KTool
local Slider = CS.UnityEngine.UI.Slider
------------ import ------------

------------ define ------------
local CardHeadNodePath = "Game.Behaviours.CardHeadNode"
local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
------------ define ------------

---@class TakeoutTeamHeadNode
local TakeoutTeamHeadNode = Class('TakeoutTeamHeadNode')

function TakeoutTeamHeadNode:__init()
    self.Empty = nil
    self.Content = nil
    ---子节点
    self.ContentBgUnderWay = nil
    self.ContentHeadNode = nil
    self.ContentSoulPoint = nil
    self.ContentSoulPointIcon = nil
    self.ContentSoulPointNumberText = nil
end

function TakeoutTeamHeadNode:__delete()
    self.Empty = nil
    self.Content = nil
    self.ContentBgUnderWay = nil
    self.ContentHeadNode = nil
    self.ContentSoulPoint = nil
    self.ContentSoulPointIcon = nil
    self.ContentSoulPointNumberText = nil
end

function TakeoutTeamHeadNode:Awake()
    ---@type UnityEngine.RectTransform
    local trans = self.controller.transform
    self.Empty = trans:Find("Empty")
    self.Content = trans:Find("Content")
    self.ContentBgUnderWay = self.Content:Find("ImgUnderway")
    self.ContentHeadNode = self.Content:Find("CommonSmallHeadNode")
    self.ContentSoulPoint = self.Content:Find("SoulPoint")
    self.ContentSoulPointIcon = self.Content:Find("SoulPoint/ImgAttribute")
    local sliderTrans = self.ContentSoulPoint:Find("Slider")
    if sliderTrans then
        self.ContentSoulPointSlider = kTool.GetComponent(sliderTrans.gameObject, typeof(Slider))
    end
    self.ContentSoulPointNumberText = self.Content:Find("SoulPoint/TextNumber")
end

---FreshUI
---@param cardDojo CardDojo
function TakeoutTeamHeadNode:FreshUI(cardDojo)
    if isNull(cardDojo) then
        kTool.SetActive(self.Empty.gameObject, true)
        kTool.SetActive(self.Content.gameObject, false)
    else
        kTool.SetActive(self.Empty.gameObject, false)
        kTool.SetActive(self.Content.gameObject, true)
        kTool.SetActive(self.ContentHeadNode.gameObject, true)
        kTool.SetActive(self.ContentSoulPoint.gameObject, true)
        ---@type CardHeadNode
        local env = CfUtils.GetLuaScr(self.ContentHeadNode.gameObject, CardHeadNodePath)
        env:FreshNode(cardDojo, false)
        env:SetRookieStatus(true)
        local energy = checkNumber(cardDojo.cafeEnergy)
        local mood = CardConfMgr:GetInstance():GetCardMoodByCardIdLevel(cardDojo.cardId, cardDojo.favorabilityLevel)
        if self.ContentSoulPointSlider then
            self.ContentSoulPointSlider.value = energy / math.max(1, mood)
        end
        CfUtils.FillText(self.ContentSoulPointNumberText, energy)
        MaidCoffeeUtils.FillSoulImage(self.ContentSoulPointIcon, energy)
    end
end

function TakeoutTeamHeadNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TakeoutTeamHeadNode